  let value:f32=(2.*t3-3.*t2+1.)*a+(t3-2.*t2+t)*m0+(-2.*t3+3.*t2)*b+(t3-t2)*m1;
  let derivative:f32=((6.*t2-6.*t)*a+(3.*t2-4.*t+1.)*m0+(-6.*t2+6.*t)*b+(3.*t2-2.*t)*m1)/step;
  return vec2f(value,derivative);
