  let along:f32=route.x;let across:f32=route.y;let scale:f32=u.river.y;
  let time:f32=u.eye.w;let evolution:f32=(u.water.y+u.river.x*.5)*.025;let speed:f32=u.river.x+u.water.y*.08;
